        if (!valid) allValid = false;
      });

      if (!allValid) {
        // Focus first invalid input for accessibility
        if (firstInvalid) getInput(firstInvalid).focus();
        status.textContent =
          "Please correct the errors above before submitting.";
        status.className = "error";
        return;
      }

