.field-hint {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  line-height: 1.4;
  display: none;
  align-items: center;
  gap: 0.3rem;
}

.field-error::before {
  content: "⚠";
  font-size: 0.875rem;
  flex-shrink: 0;
}

.field-error.visible {
  display: flex;
}

/* ── Submit button ── */
.btn-submit {
  margin-top: 0.625rem;
  width: 100%;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1rem;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
  outline: none;
  /* transparent outline for forced-colors */
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(99,102,241,0.3);
}

.btn-submit:active {
  transform: translateY(1px);
}

/* ── Status banner ── */
#form-status {
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  display: none;
}

