  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .form-field input,
  .btn-submit {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .required-mark { color: LinkText; }
  .field-error    { color: LinkText; }
}
