  letter-spacing: 0.01em;
}

.required-mark {
  color: var(--color-required);
  margin-left: 0.25rem;
  font-size: 0.875rem;
  font-weight: 700;
  line-height: 1;
  vertical-align: middle;
}

.field-optional {
  color: var(--color-text-muted);
  font-size: 0.75rem;
  font-weight: 400;
  margin-left: 0.375rem;
}

.form-field input {
  background: var(--color-surface-2);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  color: var(--color-text);
  font-size: 1rem;
  padding: 0.6875rem 0.875rem;
  width: 100%;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}

.form-field input::placeholder { color: var(--color-text-muted); opacity: 1; }

.form-field input:hover:not(:disabled) {
  border-color: #3d4268;
}

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.25);
  /* transparent outline ensures visibility in forced-colors */
  outline: 2px solid transparent;
}

.form-field input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}

.form-field input[aria-invalid="true"]:focus {
  border-color: var(--color-border-error);
  box-shadow: 0 0 0 3px rgba(248,113,113,0.25);
}

/* ── Helper / error text ── */
.field-hint {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  line-height: 1.4;
  display: none;
  align-items: center;
  gap: 0.3rem;
}

.field-error::before {
  content: "⚠";
  font-size: 0.875rem;
  flex-shrink: 0;
}

.field-error.visible {
  display: flex;
}

/* ── Submit button ── */
.btn-submit {
  margin-top: 0.625rem;
  width: 100%;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1rem;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
  outline: none;
  /* transparent outline for forced-colors */
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(99,102,241,0.3);
}

.btn-submit:active {
  transform: translateY(1px);
}

/* ── Status banner ── */
#form-status {
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  display: none;
}

#form-status.success {
  display: block;
  background: rgba(52,211,153,0.12);
  border: 1px solid var(--color-success);
  color: var(--color-success);
}

#form-status.error {
  display: block;
  background: rgba(248,113,113,0.1);
  border: 1px solid var(--color-border-error);
  color: var(--color-error);
}

/* ── Required legend ── */
.required-legend {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}

.required-legend .required-mark {
  font-size: 0.875rem;
}

/* ── Reflow ── */
@media (max-width: 320px) {
  .card { padding: 1.5rem 1rem; }
}

/* ── Screen-reader only ── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .form-field input,
  .btn-submit {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .required-mark { color: LinkText; }
  .field-error    { color: LinkText; }
}
